import { existsSync, readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { mergeScene } from "./glb-models";

// Evolved 4x4 zoned landmarks, generated by blender/buildings_evolved.py.
const X4_IDS = [5, 10, 18, 20, 37, 38];
const path = (n: number) => `public/models/x4/${String(n).padStart(2, "0")}.glb`;
const present = X4_IDS.filter((n) => existsSync(path(n)));
const tris = (g: THREE.BufferGeometry) => (g.index ? g.index.count : g.attributes.position.count) / 3;
function load(file: string): Promise<THREE.Group> {
  const b = readFileSync(file), ab = b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength);
  return new Promise((res, rej) => new GLTFLoader().parse(ab, "", (g) => res(g.scene), rej));
}

describe("4x4 evolved building variants (x4)", () => {
  it.skipIf(present.length === 0)("fits the authored 4x4 footprint and its documented per-lot budget", async () => {
    for (const n of present) {
      const f = path(n), m = mergeScene(await load(f));
      expect(m, f).not.toBeNull();
      const g = m!.geometry; g.computeBoundingBox(); const b = g.boundingBox!;
      expect(b.min.x, f).toBeGreaterThanOrEqual(-2.01); expect(b.max.x, f).toBeLessThanOrEqual(2.01);
      expect(b.min.z, f).toBeGreaterThanOrEqual(-2.01); expect(b.max.z, f).toBeLessThanOrEqual(2.01);
      expect(b.min.y, f).toBeGreaterThanOrEqual(-0.01); expect(b.max.y, f).toBeLessThan(6.2);
      expect(tris(g), f).toBeLessThanOrEqual(2800); expect(m!.materials.length, f).toBeGreaterThan(0);
    }
  });
});
